@php($album=$publication->album) @php($matching=$album->offers->where('format',$publication->format)) @php($sellerCount=$matching->unique('store_id')->count())
<a class="album-card" data-catalog-product href="{{ route('album',[$album,$publication->format,'return_to'=>request()->getRequestUri()]) }}"><div class="cover"><span class="cover-format">{{ $publication->format==='cd'?'CD':'VINILO' }}</span>@if($image=$matching->firstWhere('image','!=',null)?->image)<img data-cover-image src="{{ $image }}" alt="{{ $album->title }}" loading="lazy" referrerpolicy="no-referrer">@else<div class="cover-placeholder"><span class="disc"></span></div>@endif<span class="cover-action">Comparar precios</span></div><div class="card-info"><span class="card-artist">{{ $album->artist }}</span><h3>{{ $album->title }}</h3>@php($cheapest=$matching->where('currency','CLP')->sortBy('price')->first())@php($drop=$cheapest?->getRelation('initialDiscount'))@if($drop)<span class="catalog-drop-percent">↓ {{ number_format($drop['percent'],1,',','.') }}% en {{ $cheapest->store->name }}</span>@endif<div class="card-price">@foreach($matching->groupBy('currency') as $currency=>$offers)<p><span>Desde</span> <strong>{{ $currency }} {{ number_format($offers->min('price'),$currency==='CLP'?0:2,',','.') }}</strong></p>@endforeach</div><div class="card-bottom"><span>En {{ $sellerCount }} {{ $sellerCount===1?'tienda':'tiendas' }}</span><span class="card-compare-label">Comparar</span></div></div></a>
